// RemoteOK returns one item per job. The first item is their legal notice, so skip anything without an id.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.id || !j.position) continue;
  const { description, ...rest } = j;
  out.push({ json: {
    source: 'remoteok',
    source_job_id: String(j.id),
    title: j.position,
    company_name: j.company,
    company_slug: null,
    company_domain: null,
    url: j.url,
    apply_url: j.apply_url || j.url,
    published_at: j.date,
    location_restrictions: j.location ? [j.location] : [],
    seniority: [],
    tags: j.tags || [],
    description: description || '',
    raw: rest
  }});
}
return out;

// Remotive returns one item holding a "jobs" list. Turn each job into the same shape as RemoteOK.
const out = [];
for (const item of $input.all()) {
  for (const j of (item.json.jobs || [])) {
    const { description, ...rest } = j;
    out.push({ json: {
      source: 'remotive',
      source_job_id: String(j.id),
      title: j.title,
      company_name: j.company_name,
      company_slug: null,
      company_domain: null,
      url: j.url,
      apply_url: j.url,
      published_at: j.publication_date,
      location_restrictions: j.candidate_required_location ? [j.candidate_required_location] : [],
      seniority: [],
      tags: j.tags || [],
      description: description || '',
      raw: rest
    }});
  }
}
return out;

// Hiring gate: keep only GTM-type titles posted in the last 30 days, and drop duplicates.
const TITLE = /(\bgtm\b|go[- ]to[- ]market|rev ?ops|revenue operations|marketing operations|marketing ops|sales operations|sales ops|growth operations|growth ops|\bcrm\b|salesforce (admin|administrator|developer|consultant)|hubspot|marketing automation)/i;
const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.title || !TITLE.test(j.title)) continue;
  const t = Date.parse(j.published_at);
  if (isNaN(t) || t < cutoff) continue;
  const key = j.source + ':' + j.source_job_id;
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: { ...j, published_at: new Date(t).toISOString() } });
}
return out;

// One search per GTM keyword. Himalayas searches titles and descriptions; the GTM filter later keeps only matching titles.
return [
  'revenue operations', 'revops', 'gtm engineer', 'go-to-market',
  'marketing operations', 'sales operations', 'growth operations',
  'crm manager', 'hubspot', 'salesforce administrator', 'marketing automation'
].map(q => ({ json: { q } }));

// Each item is one page of Himalayas results holding a "jobs" list. Turn each job into the same shape as the other sources.
const toText = x => typeof x === 'string' ? x : (x && (x.name || x.alpha2 || x.code)) || JSON.stringify(x);
const out = [];
for (const item of $input.all()) {
  for (const j of (item.json.jobs || [])) {
    const { description, ...rest } = j;
    const ts = typeof j.pubDate === 'number' ? (j.pubDate > 1e12 ? j.pubDate : j.pubDate * 1000) : Date.parse(j.pubDate);
    out.push({ json: {
      source: 'himalayas',
      source_job_id: String(j.guid || j.applicationLink),
      title: j.title,
      company_name: j.companyName,
      company_slug: j.companySlug || null,
      company_domain: null,
      url: j.guid && String(j.guid).startsWith('http') ? j.guid : j.applicationLink,
      apply_url: j.applicationLink,
      published_at: isNaN(ts) ? null : new Date(ts).toISOString(),
      location_restrictions: (j.locationRestrictions || []).map(toText),
      seniority: (j.seniority || []).map(toText),
      tags: (j.categories || []).map(toText),
      description: description || '',
      raw: rest
    }});
  }
}
return out;
